const POSITIVE = ['breathtaking', 'iconic', 'worth', 'recommended', 'great', 'must visit', 'educational', 'sunrise', 'authentic', 'convenient', 'excellent', 'easy', 'frequent', 'available', 'cheap', 'best', 'families'];
const NEGATIVE = ['difficult', 'crowded', 'long', 'trap', 'overpriced', 'expensive', 'limited', 'chaotic', 'maintenance', 'security queues', 'parking is difficult'];
const COLORS = ['#0f766e', '#2563eb', '#e15f41', '#d99a16', '#168354', '#7c3aed', '#c24136', '#0891b2'];
const state = { selected: TOURISM_DATA[0], tab: 'sentiment' };
let imageRequestId = 0;

const $ = (id) => document.getElementById(id);
const byPlace = new Map(TOURISM_DATA.map(item => [item.place.toLowerCase(), item]));

function splitReviews(item) {
  return item.feedback.split('|').map(part => {
    const clean = part.trim().replace(/^Review\s+\d+:\s*/i, '');
    const transport = (clean.match(/Transport:\s*(.*?)(?:\.\s*Food:|$)/i) || [,''])[1].trim();
    const food = (clean.match(/Food:\s*(.*)$/i) || [,''])[1].trim();
    const attraction = clean.replace(/Transport:.*$/i, '').trim();
    const sentiment = scoreSentiment(clean, item.rating);
    return { clean, transport, food, attraction, sentiment };
  });
}

function scoreSentiment(text, rating) {
  const lower = text.toLowerCase();
  let score = rating >= 4.3 ? 1 : rating <= 3.4 ? -1 : 0;
  POSITIVE.forEach(word => { if (lower.includes(word)) score += 1; });
  NEGATIVE.forEach(word => { if (lower.includes(word)) score -= 1; });
  if (score >= 2) return 'positive';
  if (score <= -1) return 'negative';
  return 'neutral';
}

function countBy(values) {
  return values.reduce((acc, value) => {
    const key = value || 'Not mentioned';
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
}

function sentimentCounts(reviews) {
  return ['positive', 'neutral', 'negative'].reduce((acc, key) => {
    acc[key] = reviews.filter(review => review.sentiment === key).length;
    return acc;
  }, {});
}

function init() {
  const countries = ['All countries', ...Array.from(new Set(TOURISM_DATA.map(item => item.country))).sort()];
  $('countryFilter').innerHTML = countries.map(country => `<option value="${country}">${country}</option>`).join('');
  $('countryFilter').addEventListener('change', updatePlaceOptions);
  $('analyzeBtn').addEventListener('click', analyzeFromInput);
  $('placeSearch').addEventListener('keydown', event => { if (event.key === 'Enter') analyzeFromInput(); });
  document.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => switchTab(button.dataset.tab)));
  updatePlaceOptions();
  selectPlace(TOURISM_DATA[0]);
}

function updatePlaceOptions() {
  const country = $('countryFilter').value;
  const places = TOURISM_DATA.filter(item => country === 'All countries' || item.country === country);
  $('placeOptions').innerHTML = places.map(item => `<option value="${item.place}">${item.country}</option>`).join('');
  if (!places.includes(state.selected)) selectPlace(places[0] || TOURISM_DATA[0]);
}

function analyzeFromInput() {
  const query = $('placeSearch').value.trim().toLowerCase();
  const country = $('countryFilter').value;
  const scoped = TOURISM_DATA.filter(item => country === 'All countries' || item.country === country);
  const exact = byPlace.get(query);
  const fuzzy = scoped.find(item => item.place.toLowerCase().includes(query)) || TOURISM_DATA.find(item => item.place.toLowerCase().includes(query));
  selectPlace(exact || fuzzy || scoped[0] || TOURISM_DATA[0]);
}

function selectPlace(item) {
  state.selected = item;
  $('placeSearch').value = item.place;
  $('selectedPlace').textContent = item.place;
  $('selectedCountry').textContent = item.country;
  $('ratingValue').textContent = item.rating.toFixed(1);
  $('ratingStars').textContent = starText(item.rating);
  $('foodLevel').textContent = item.foodAvailability;
  $('transportLevel').textContent = item.transportFacilities;
  $('foodSignal').textContent = foodSignal(item.foodAvailability);
  $('transportSignal').textContent = transportSignal(item.transportFacilities);
  renderAll();
}

function switchTab(tab) {
  state.tab = tab;
  document.querySelectorAll('.tab').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tab));
  document.querySelectorAll('.tab-panel').forEach(panel => panel.classList.toggle('active', panel.id === tab));
  renderAll();
}

function starText(rating) {
  const full = Math.round(rating);
  return '?'.repeat(full) + '?'.repeat(Math.max(0, 5 - full));
}

function foodSignal(level) {
  return level === 'High' ? 'Strong food access' : level === 'Medium' ? 'Moderate choice' : 'Needs food planning';
}

function transportSignal(level) {
  return level === 'Excellent' ? 'Very accessible' : level === 'Good' ? 'Comfortable access' : level === 'Average' ? 'Plan route ahead' : 'Access is a concern';
}

function renderAll() {
  const item = state.selected;
  const reviews = splitReviews(item);
  renderSentiment(reviews);
  renderFood(item, reviews);
  renderTransport(item, reviews);
  renderAttraction(item, reviews);
  renderImages(item);
}

function renderSentiment(reviews) {
  const counts = sentimentCounts(reviews);
  renderPictograms('sentimentPictograms', [
    { icon: '😊', label: 'Positive', value: counts.positive, tone: 'good' },
    { icon: '😐', label: 'Neutral', value: counts.neutral, tone: 'warn' },
    { icon: '☹', label: 'Negative', value: counts.negative, tone: 'bad' }
  ]);
  const ordered = [...reviews].sort((a, b) => sentimentWeight(b.sentiment) - sentimentWeight(a.sentiment)).slice(0, 8);
  $('reviewList').innerHTML = ordered.map(review => `<div class="review ${review.sentiment}"><b>${review.sentiment}</b><span>${escapeHtml(review.clean)}</span></div>`).join('');
}

function sentimentWeight(sentiment) {
  return sentiment === 'positive' ? 3 : sentiment === 'neutral' ? 2 : 1;
}

function renderFood(item, reviews) {
  const counts = countBy(reviews.map(review => review.food));
  const entries = topEntries(counts, 7);
  renderPictograms('foodPictograms', entries.slice(0, 6).map(([label, value]) => ({
    icon: foodIcon(label),
    label,
    value,
    tone: /overpriced|limited|carry|trap/i.test(label) ? 'bad' : 'good'
  })));
  $('foodInsights').innerHTML = [
    ['Dataset level', item.foodAvailability],
    ['Most repeated comment', entries[0]?.[0] || 'Not available'],
    ['Attention needed', entries.find(([key]) => /overpriced|limited|carry|trap/i.test(key))?.[0] || 'No major food issue repeated']
  ].map(metricRow).join('');
}

function renderTransport(item, reviews) {
  const counts = countBy(reviews.map(review => review.transport));
  const entries = topEntries(counts, 7);
  renderPictograms('transportPictograms', entries.slice(0, 6).map(([label, value]) => ({
    icon: transportIcon(label),
    label,
    value,
    tone: /difficult|crowded|expensive|chaotic/i.test(label) ? 'bad' : 'good'
  })));
  $('transportInsights').innerHTML = [
    ['Dataset level', item.transportFacilities],
    ['Most repeated comment', entries[0]?.[0] || 'Not available'],
    ['Convenience mentions', reviews.filter(r => /easy|excellent|convenient|frequent|walking|cheap/i.test(r.transport)).length + ' of ' + reviews.length],
    ['Pain point', entries.find(([key]) => /difficult|crowded|expensive|chaotic/i.test(key))?.[0] || 'No major transport issue repeated']
  ].map(metricRow).join('');
}

function renderAttraction(item, reviews) {
  const themes = {
    'Photography': /photography|views|breathtaking/i,
    'Family friendly': /families|educational/i,
    'Iconic value': /iconic|worth|must visit|sunrise/i,
    'Crowd pressure': /crowded|queues|security/i,
    'Maintenance': /maintenance/i,
    'Tourist trap risk': /trap|overpriced|expensive/i
  };
  const labels = Object.keys(themes);
  const values = labels.map(label => reviews.filter(review => themes[label].test(review.clean)).length);
  renderPictograms('attractionPictograms', labels.map((label, index) => ({
    icon: attractionIcon(label),
    label,
    value: values[index],
    tone: /Crowd|Maintenance|trap/i.test(label) ? 'bad' : 'good'
  })));
  const actions = buildActions(item, reviews, labels, values);
  $('actionList').innerHTML = actions.map(([title, detail]) => `<div class="action-row"><span>${title}</span><strong>${detail}</strong></div>`).join('');
}

function renderPictograms(targetId, items) {
  $(targetId).innerHTML = items.map(item => {
    const units = Math.max(1, Math.min(8, item.value));
    const icons = Array.from({ length: units }, () => `<span>${item.icon}</span>`).join('');
    return `<div class="pictogram-card ${item.tone}"><div class="pictogram-icons">${icons}</div><div><strong>${escapeHtml(String(item.value))}</strong><p>${escapeHtml(item.label)}</p></div></div>`;
  }).join('');
}

function foodIcon(label) {
  if (/water|carry/i.test(label)) return '💧';
  if (/cafe/i.test(label)) return '☕';
  if (/street|traditional|authentic/i.test(label)) return '🍲';
  if (/overpriced|trap|expensive/i.test(label)) return '⚠';
  return '🍽';
}

function transportIcon(label) {
  if (/train|metro/i.test(label)) return '🚆';
  if (/taxi|uber|car/i.test(label)) return '🚕';
  if (/walking/i.test(label)) return '🚶';
  if (/bus|shuttle/i.test(label)) return '🚌';
  if (/parking|difficult|crowded/i.test(label)) return '⚠';
  return '🧭';
}

function attractionIcon(label) {
  if (/Photography/i.test(label)) return '📷';
  if (/Family/i.test(label)) return '👪';
  if (/Iconic/i.test(label)) return '★';
  if (/Crowd/i.test(label)) return '👥';
  if (/Maintenance/i.test(label)) return '🛠';
  return '⚠';
}

async function renderImages(item) {
  const requestId = ++imageRequestId;
  $('imageGrid').innerHTML = '<div class="image-loading">Loading place images...</div>';
  const images = await fetchCommonsImages(item);
  if (requestId !== imageRequestId) return;

  if (!images.length) {
    $('imageGrid').innerHTML = `<div class="image-loading">No online image found for ${escapeHtml(item.place)}.</div>`;
    return;
  }

  $('imageGrid').innerHTML = images.slice(0, 4).map((image, index) => {
    return `<figure class="place-photo"><img src="${image.url}" alt="${escapeHtml(item.place)} image ${index + 1}" loading="lazy"><figcaption>${escapeHtml(item.place)}, ${escapeHtml(item.country)}</figcaption></figure>`;
  }).join('');
}

async function fetchCommonsImages(item) {
  const search = encodeURIComponent(`${item.place} ${item.country}`);
  const url = `https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${search}&gsrnamespace=6&gsrlimit=8&prop=imageinfo&iiprop=url&iiurlwidth=900&format=json&origin=*`;
  try {
    const response = await fetch(url);
    if (!response.ok) return [];
    const data = await response.json();
    const pages = Object.values(data.query?.pages || {});
    return pages
      .map(page => page.imageinfo?.[0])
      .filter(info => info?.thumburl || info?.url)
      .map(info => ({ url: info.thumburl || info.url }));
  } catch (error) {
    return [];
  }
}

function buildActions(item, reviews, labels, values) {
  const actions = [];
  const crowd = values[labels.indexOf('Crowd pressure')];
  const maintenance = values[labels.indexOf('Maintenance')];
  const trap = values[labels.indexOf('Tourist trap risk')];
  actions.push(['Promote strength', labels[values.indexOf(Math.max(...values))]]);
  actions.push(['Best visitor message', item.rating >= 4.2 ? 'Highlight high satisfaction' : 'Set expectations clearly']);
  actions.push(['Food action', item.foodAvailability === 'Limited' ? 'Add food map and water tips' : 'Show nearby food options']);
  actions.push(['Transport action', /Difficult|Average/.test(item.transportFacilities) ? 'Publish route and parking guidance' : 'Feature easy access']);
  actions.push(['Visitor timing', crowd > 4 ? 'Recommend early morning or weekday visits' : 'Promote flexible visiting hours']);
  actions.push(['Photo strategy', values[labels.indexOf('Photography')] > 3 ? 'Create photo spots and viewing points' : 'Add visual highlights to promotions']);
  actions.push(['Family plan', values[labels.indexOf('Family friendly')] > 2 ? 'Offer family-friendly routes' : 'Improve family guidance']);
  actions.push(['Local experience', item.foodAvailability === 'High' ? 'Bundle food and culture tips' : 'List safe nearby food options']);
  if (crowd > 4) actions.push(['Crowd control', 'Suggest weekday and early visits']);
  if (maintenance > 2) actions.push(['Operations', 'Prioritize cleanliness checks']);
  if (trap > 3) actions.push(['Trust signal', 'Warn about inflated tourist prices']);
  return actions.slice(0, 9);
}

function topEntries(counts, limit) {
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, limit);
}

function average(values) {
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function metricRow([label, value]) {
  return `<div class="metric-row"><span>${label}</span><strong>${escapeHtml(String(value))}</strong></div>`;
}

function drawDonut(canvasId, labels, values, colors) {
  const canvas = prepareCanvas(canvasId);
  const ctx = canvas.getContext('2d');
  const total = values.reduce((sum, value) => sum + value, 0) || 1;
  const cx = canvas.width * 0.32;
  const cy = canvas.height * 0.5;
  const radius = Math.min(canvas.width, canvas.height) * 0.28;
  let start = -Math.PI / 2;
  values.forEach((value, index) => {
    const end = start + (value / total) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, radius, start, end);
    ctx.closePath();
    ctx.fillStyle = colors[index];
    ctx.fill();
    start = end;
  });
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.arc(cx, cy, radius * 0.58, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  drawLegend(ctx, labels, values, colors, canvas.width * 0.62, canvas.height * 0.28);
}

function drawBar(canvasId, labels, values, colors) {
  const canvas = prepareCanvas(canvasId);
  const ctx = canvas.getContext('2d');
  const max = Math.max(...values, 1);
  const left = 38;
  const bottom = canvas.height - 44;
  const width = canvas.width - 58;
  const barW = Math.max(22, width / values.length - 16);
  ctx.strokeStyle = '#d9e0e8';
  ctx.beginPath();
  ctx.moveTo(left, 18);
  ctx.lineTo(left, bottom);
  ctx.lineTo(canvas.width - 14, bottom);
  ctx.stroke();
  values.forEach((value, index) => {
    const x = left + 14 + index * (width / values.length);
    const h = (value / max) * (bottom - 40);
    ctx.fillStyle = colors[index % colors.length];
    roundRect(ctx, x, bottom - h, barW, h, 7);
    ctx.fill();
    ctx.fillStyle = '#17212b';
    ctx.font = '700 13px Segoe UI, Arial';
    ctx.textAlign = 'center';
    ctx.fillText(value, x + barW / 2, bottom - h - 8);
    wrapLabel(ctx, labels[index], x + barW / 2, bottom + 15, Math.min(86, width / values.length), 10);
  });
}

function drawHorizontalBar(canvasId, labels, values, colors) {
  const canvas = prepareCanvas(canvasId);
  const ctx = canvas.getContext('2d');
  const max = 5;
  const left = 160;
  const top = 22;
  const rowH = (canvas.height - 42) / labels.length;
  labels.forEach((label, index) => {
    const y = top + index * rowH;
    const w = (values[index] / max) * (canvas.width - left - 54);
    ctx.fillStyle = '#eef2f7';
    roundRect(ctx, left, y + 6, canvas.width - left - 54, 18, 7);
    ctx.fill();
    ctx.fillStyle = colors[index];
    roundRect(ctx, left, y + 6, w, 18, 7);
    ctx.fill();
    ctx.fillStyle = '#17212b';
    ctx.font = '700 12px Segoe UI, Arial';
    ctx.textAlign = 'right';
    ctx.fillText(trimLabel(label, 22), left - 10, y + 20);
    ctx.textAlign = 'left';
    ctx.fillText(values[index].toFixed(1), left + w + 8, y + 20);
  });
}

function drawLegend(ctx, labels, values, colors, x, y) {
  labels.forEach((label, index) => {
    const yy = y + index * 34;
    ctx.fillStyle = colors[index];
    roundRect(ctx, x, yy, 18, 18, 5);
    ctx.fill();
    ctx.fillStyle = '#17212b';
    ctx.font = '700 14px Segoe UI, Arial';
    ctx.textAlign = 'left';
    ctx.fillText(`${label}: ${values[index]}`, x + 28, yy + 14);
  });
}

function prepareCanvas(id) {
  const canvas = $(id);
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.max(320, Math.floor(rect.width * dpr));
  canvas.height = Math.floor((Number(canvas.getAttribute('height')) || 260) * dpr);
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  canvas.width = Math.max(320, Math.floor(rect.width));
  canvas.height = Number(canvas.getAttribute('height')) || 260;
  return canvas;
}

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, Math.abs(h) / 2, Math.abs(w) / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function wrapLabel(ctx, text, x, y, maxWidth, lineHeight) {
  ctx.fillStyle = '#667085';
  ctx.font = '600 10px Segoe UI, Arial';
  ctx.textAlign = 'center';
  const words = trimLabel(text, 28).split(' ');
  let line = '';
  let lines = [];
  words.forEach(word => {
    const test = line ? line + ' ' + word : word;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = word;
    } else {
      line = test;
    }
  });
  lines.push(line);
  lines.slice(0, 3).forEach((part, i) => ctx.fillText(part, x, y + i * lineHeight));
}

function trimLabel(text, limit) {
  return text.length > limit ? text.slice(0, limit - 1) + '...' : text;
}

function escapeHtml(value) {
  return value.replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
}

window.addEventListener('resize', () => renderAll());
init();
